svg.script:
(function () {
  const svg = document.getElementById('antisymmetry-hexagon');
  const cells = Array.from(svg.querySelectorAll('.hit-cell'));
  const axis1 = svg.getElementById('axis-1');
  const axis2 = svg.getElementById('axis-2');
  let pinned = null;

  const rowExtents = {"0": [169.7, 450.3, 98.0], "1": [122.93, 497.07, 179.0], "2": [76.17, 543.83, 260.0], "3": [122.93, 497.07, 341.0], "4": [169.7, 450.3, 422.0]};

  function findCell(id) {
    return cells.find(node => node.dataset.id === id) || null;
  }

  function setLine(axis, row) {
    const ext = rowExtents[String(row)];
    if (!ext) {
      axis.classList.remove('on');
      return;
    }
    axis.setAttribute('x1', ext[0]);
    axis.setAttribute('y1', ext[2]);
    axis.setAttribute('x2', ext[1]);
    axis.setAttribute('y2', ext[2]);
    axis.classList.add('on');
  }

  function clearVisuals() {
    svg.querySelectorAll('.pair-wash.on').forEach(el => el.classList.remove('on'));
    svg.querySelectorAll('.cell-outline.active').forEach(el => el.classList.remove('active'));
    svg.querySelectorAll('.number.active').forEach(el => el.classList.remove('active'));
    axis1.classList.remove('on');
    axis2.classList.remove('on');
  }

  function activateById(id) {
    clearVisuals();
    if (!id) return;
    const el = findCell(id);
    if (!el) return;
    const other = findCell(el.dataset.opposite);
    const pair = [el, other].filter(Boolean);

    pair.forEach(node => {
      const cid = node.dataset.id;
      const wash = svg.getElementById(cid + '_wash');
      const outline = svg.getElementById(cid + '_outline');
      const number = svg.getElementById(cid + '_number');
      if (wash) wash.classList.add('on');
      if (outline) outline.classList.add('active');
      if (number) number.classList.add('active');
    });

    const row1 = Number(el.dataset.row);
    const row2 = other ? Number(other.dataset.row) : row1;
    setLine(axis1, row1);
    if (row2 !== row1) setLine(axis2, row2);
    else axis2.classList.remove('on');
  }

  function hoverCell(el) {
    if (pinned) return;
    activateById(el.dataset.id);
  }

  function clearHover() {
    if (pinned) activateById(pinned.dataset.id);
    else clearVisuals();
  }

  function togglePin(el) {
    if (pinned === el) {
      pinned = null;
      clearVisuals();
    } else {
      pinned = el;
      activateById(el.dataset.id);
    }
  }

  cells.forEach(el => {
    el.addEventListener('mouseenter', () => hoverCell(el));
    el.addEventListener('mouseleave', clearHover);
    el.addEventListener('focus', () => hoverCell(el));
    el.addEventListener('blur', clearHover);
    el.addEventListener('click', (ev) => {
      ev.preventDefault();
      togglePin(el);
    });
    el.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter' || ev.key === ' ') {
        ev.preventDefault();
        togglePin(el);
      } else if (ev.key === 'Escape') {
        ev.preventDefault();
        pinned = null;
        clearVisuals();
      }
    });
  });

  svg.addEventListener('mouseleave', () => {
    if (!pinned) clearVisuals();
  });
})();
